prompt._raw_prompt:
"{
  "图像元数据与投影标准": {
    "数据类型": "360度等距柱状全景图",
    "投影几何": "完整球形等距柱状投影",
    "画布物理规格": "标准2比1宽高比",
    "期望渲染精度": "超高分辨率极清画质"
  },
  "核心场景空间构图": {
    "地理空间轴": "一个完整的360度视角的崎岖挪威罗弗敦群岛（或其他类似的岩石海岸）海湾。日落核心位于西面地平线，由厚重的风暴云环绕。相机位于海滩中央。向北看是连续的雄伟山脉，向东看是深邃的海湾和远处一个渔村的灯火，向南看是汹涌的大海和更多的小岛。整个场景形成一个封闭的、环绕式的环境，呈现极端的荒野感。",
    "相机基准位置": "绝对中心原点",
    "相机垂直高度": "海滩水平线附近，低角度以增强前景巨石和汹涌海浪的视觉冲击力",
    "视场角覆盖率": "水平360度环绕，垂直180度穹顶",
    "数学投影行为": "标准等距柱状畸变，为虚拟现实渲染器确保无缝拼接",
    "宏观气象环境": "强烈的日落与风暴云结合，营造出戏剧性的光影对比和汹涌的海况。",
    "光学景深控制": "全景深锁定，确保远近景皆清晰可见，前景岩石纹理和远山细节均锐利"
  },
  "前景视觉元素与动态捕捉": {
    "前景主体视图": "环绕相机的铺满湿润、光滑、深色巨石和鹅卵石的海滩。长时间曝光捕捉的白色丝绸般的海浪水流，从360度各个方向拍打并包裹着岩石，水流具有自然的动感和流动性，呈现出梦幻般的丝滑纹理。水流覆盖整个海滩，与周围岩石完美融合。",
    "动态时间线行为": "长时间曝光摄影效果，捕捉水流的丝绸化和天空云层的流动，无瞬间运动模糊。",
    "物理真度约束": "完全遵循现实世界物理规律，光影、材质、比例与重力关系自然"
  },
  "中景地貌与实体特征": {
    "地形地貌特征": "汹涌的大海在前方（西面）和两侧（北面和南面）。中景海面上，那个孤立的、高耸的岩石尖塔清晰可见。右侧的巨大、呈三角形的山峰和左侧更远的山脉连接，形成一个半环绕海湾的连续、宏伟的山脉链。山脉表面有积雪和风化的纹理。中景海面波浪汹涌，反射着日落的色彩。",
    "建筑与村落基建": "在东面海湾的极远处，增加一个微小的、灯光闪烁的罗弗敦渔村（如雷讷或奥村）的轮廓，以增加现实感和叙事性，并使其成为一个完整的环绕。",
    "大气粒子与云雾": "空气中弥漫着细微的水雾和大气颗粒物，增强空间深度感，特别是在远景山脉和海面上方。"
  },
  "远景环境与天空穹顶": {
    "远景边界景观": "视线尽头是连绵不断的崎岖山脉，将海湾封闭，形成一个完整的360度环绕。",
    "天顶与天空表现": "完整的360度球形穹顶天空。西面是核心日落，深橙色、金色、黄色的云层从地平线升起，被巨大的深灰色、带紫色的风暴云环绕，这些风暴云呈环形向天空四周扩散，纹理丰富。东面的天空（180度相反）是深邃的、过渡性的蓝夜，能看到几颗早期星星和更柔和的云层。整个天空的云层纹理丰富且连续。"
  },
  "微观材质与物理表面特性": {
    "宏观材质特征": "材质具备细腻的微观纹理，严禁出现无细节、平滑无质感的计算机生成表面。前景湿润的岩石表面、海水的丝滑纹理、山脉的岩石纹理都清晰可见。",
    "物理使用痕迹": "微小自然磨损、风化、风蚀或历史痕迹，强力增强画面现实主义质感。",
    "纹理随机性分布": "纹理采用非周期性、自然随机分布算法，彻底避免规律性重复贴图痕迹。"
  },
  "高动态范围光影渲染控制": {
    "主光源物理逻辑": "全局统一自然光照明，光照方向从西面的日落核心发出，光照角度和强度与光源物理位置完全对齐。",
    "阴影微观细节": "阴影边缘具备自然的物理软过渡，避免人工过度锐化。西面日落区域有强烈的暖色调高光，而东面和背光区域则呈现深沉的冷色调阴影。",
    "环境反射与反弹光": "细腻的漫反射与环境光反弹，暗部保留丰富的层次与细节。水面和岩石反射整个360度的天空和山脉色彩。",
    "高光溢出控制": "高光区域严格保留材质本身的层次与纹理，严禁产生死白过曝现象。"
  },
  "三维空间真实感与透视一致性": {
    "物体尺度关系": "所有物体严格遵循现实世界的比例尺，空间体量逻辑完全合理。前景巨石和海浪、中景小岛、远景巨大山峰和远处渔村的比例关系自然协调。",
    "透视几何一致性": "环形空间结构连贯，无任何多视点透视冲突或几何畸变错误。山脉在360度视角下形成一个连续、合理的链条。",
    "空气透视效应": "远景依物理规律轻微降低对比度与色彩饱和度，呈现深邃的空间深度感。远处山脉和渔村显得较为柔和。",
    "细节距离衰减": "视觉细节随距离增加自然衰减，保持整体画面的层次清晰度。"
  },
  "全景边界无缝拼接约束": {
    "边界物理连续性": "画布最左侧边缘与最右侧边缘实现几何级无缝拼接，图形结构完美连贯（如左侧山脉与右侧山脉无缝连接）。",
    "环形空间结构": "空间呈现绝对的环形闭合结构，家具、建筑、景观围绕中心原点均匀展开。山脉链条环绕整个场景。",
    "视觉断层绝对封杀": "左右两端色彩、光照、线条结构高度一致，图形拼接处无任何空间跳跃与视差断层。"
  },
  "空间几何结构锁定规则": {
    "微观结构边缘": "物体物理边缘略有不完美，以增强写实摄影感。岩石和山脉边缘自然不规则。",
    "拼接控制点": "拼接交界处过渡自然，严禁产生任何线条断裂、错位或图像重影。",
    "物理接触阴影": "所有物体与地面或接触面相交处，必须产生细腻的接触阴影，消除悬浮感。海浪与岩石、岩石与地面的接触阴影要处理得细腻。"
  },
  "表面反射与环境映射": {
    "物理反射类型": "严格根据材质属性物理区分镜面反射（如平静积水坑）与漫反射（如湿岩石）。长时间曝光的海水呈现柔和的漫反射。",
    "表面粗糙度映射": "非绝对镜面材质的反射需呈现模糊物理漫反射，效果必须完全符合表面粗糙度设定。湿岩石反射模糊而自然。",
    "环境闭环映射": "材质表面反射的内容必须与全景周围360度的环境闭环保持绝对一致。水面清晰反射360度天空和山脉。"
  },
  "画面纯净度与人工痕迹过滤": {
    "瑕疵与噪点控制": "允许符合胶片或相机传感器的轻微自然瑕疵，严禁数字噪点、色彩断层与压缩痕迹。保持胶片质感。",
    "无干扰视觉元素": "画面纯净，严禁出现水印、日期、文字、用户界面、人工边框或任何裁剪视窗。",
    "全局风格一致性": "整体渲染风格、艺术调性横向360度完全统一，严禁任何局部的风格断层。"
  },
  "专属场景控制路由": {
    "现代简约风格核心": "当识别为建筑或室内场景时，严格保持现代简约设计语汇，地板、墙体纹理连续，门窗结构完整不被切割。",
    "写实摄影风格锁定": "严格锁定写实摄影质感，捕捉史诗般、电影般的罗弗敦群岛自然风光，使用长时间曝光风格，避免任何现代建筑介入（除远处微小渔村），禁止电影感夸张光影，禁止奇幻与插画感。强调纹理和光影的写实性。"
  },
  "负面限制提示词矩阵": [
    "用户界面",
    "水印",
    "文字",
    "边框",
    "裁剪视图",
    "全景接缝断裂",
    "拼缝不连续",
    "低画质",
    "噪点",
    "现代建筑",
    "大型桥梁",
    "行人",
    "奇幻艺术",
    "插图",
    "过度处理"
  ]
}
